/* Prototype UX isolé : données fictives, aucune API, aucune persistance. */
const state={screen:'login',auth:false,mode:'desktop',demo:'default',feed:[{id:1,author:'Alice Demo',own:true,text:'Bienvenue sur WatYouFace. Cette publication est fictive.',likes:0,liked:false,comments:[]},{id:2,author:'Bruno Demo',own:false,text:'Je vends un vélo urbain en bon état.',likes:4,liked:false,comments:['Charlie Demo : Est-il encore disponible ?']}],messages:[{from:'Bruno Demo',text:'Bonjour Alice, le vélo est disponible.'},{from:'Alice Demo',text:'Merci, puis-je en savoir plus ?'}],market:'AVAILABLE',wallet:100,success:'',listingOpen:false,chatMobileThread:false};
const $=s=>document.querySelector(s);const app=$('#app');const announce=t=>{$('#live').textContent=t};
function setScreen(screen){state.screen=screen;state.demo='default';state.success='';render();window.scrollTo({top:0,behavior:'smooth'})}
function nav(){if(!state.auth)return '';const items=[['feed','Feed'],['chat','Chat'],['market','Marketplace'],['profile','Profil']];return `<nav class="nav" aria-label="Navigation principale">${items.map(([id,label])=>`<button data-screen="${id}" ${state.screen===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`}
function shell(content){return `<div class="shell ${state.mode==='mobile'?'force-mobile':''}"><header class="topbar"><span class="brand">WatYouFace</span>${nav()}<div class="demo-controls"><label class="sr-only" for="mode">Format</label><select id="mode" aria-label="Aperçu responsive"><option value="desktop" ${state.mode==='desktop'?'selected':''}>Desktop</option><option value="mobile" ${state.mode==='mobile'?'selected':''}>Mobile</option></select>${state.auth?`<button data-action="logout">Déconnexion</button>`:''}</div></header><main id="main" class="page">${content}</main>${state.auth?`<nav class="mobile-nav" aria-label="Navigation mobile">${[['feed','Feed'],['chat','Chat'],['market','Market'],['profile','Profil']].map(([id,label])=>`<button data-screen="${id}" ${state.screen===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`:''}</div>`}
function controls(){return state.auth?`<aside class="card notice" aria-label="États de démonstration"><strong>États de démonstration</strong><div class="row"><button class="text-button" data-demo="loading">Chargement</button><button class="text-button" data-demo="empty">Vide</button><button class="text-button" data-demo="error">Erreur</button><button class="text-button" data-demo="forbidden">Interdit</button><button class="text-button" data-demo="default">Réinitialiser</button></div></aside>`:''}
function scenarioState(){if(state.demo==='default')return '';if(state.demo==='loading')return `<section class="card state-card"><span class="loading"><span class="dot"></span>Chargement simulé…</span></section>`;if(state.demo==='empty')return `<section class="card state-card"><h2>Aucun élément disponible</h2><p>Ce scénario simule un état vide.</p><button class="secondary button" data-demo="default">Revenir au contenu</button></section>`;if(state.demo==='error')return `<section class="card state-card"><h2>Une erreur est survenue</h2><p>Il s’agit d’une simulation sans détail technique.</p><button class="primary button" data-demo="default">Réessayer</button></section>`;return `<section class="card state-card"><h2>Accès refusé</h2><p>Vous n’êtes pas autorisé à effectuer cette action.</p><button class="secondary button" data-screen="feed">Retour au feed</button></section>`}
function login(){return shell(`<section class="card" style="max-width:460px;margin:48px auto"><h1 class="page-title">Connexion</h1><p class="lead">Utilisez des données fictives : aucun mot de passe n’est traité.</p><form id="login-form"><div class="field"><label for="email">Email</label><input id="email" name="email" value="alice@example.com" autocomplete="off"><span id="email-error" class="error"></span></div><div class="field"><label for="password">Mot de passe</label><input id="password" name="password" type="password" value="prototype" autocomplete="off"><span id="login-error" class="error"></span></div><div class="row"><button class="primary button" type="submit">Se connecter</button><button class="text-button" type="button" data-action="wrong-login">Simuler erreur</button><button class="text-button" type="button" data-action="contract-refused">Contrat non accepté</button></div></form><p class="prototype-note">Pas de compte ? <button class="text-button" data-screen="register">Créer un compte</button></p></section>`)}
function register(){return shell(`<section class="card" style="max-width:520px;margin:32px auto"><h1 class="page-title">Créer un compte</h1><form id="register-form"><div class="field"><label for="username">Pseudo</label><input id="username" value="Alice Demo"><span class="error"></span></div><div class="field"><label for="register-email">Email</label><input id="register-email" value="alice@example.com"><span class="help">Adresse fictive uniquement.</span></div><div class="field"><label for="register-password">Mot de passe</label><input id="register-password" type="password" value="Prototype-1234"><span class="help">12 caractères minimum — simulation.</span></div><div class="row"><button class="primary button" type="submit">Continuer vers le contrat</button><button class="secondary button" type="button" data-screen="login">Retour connexion</button></div></form></section>`)}
function contract(){return shell(`<section class="card" style="max-width:650px;margin:32px auto"><h1 class="page-title">Contrat WatYouFace</h1><div class="notice"><strong>Version fictive du contrat</strong><p>Dans le prototype, la lecture et l’acceptation sont simulées. Aucun compte n’est créé.</p></div><div class="row" style="margin-top:16px"><button class="secondary button" data-screen="register">Refuser et revenir</button><button class="primary button" data-action="accept-contract">Accepter et créer mon compte</button></div></section>`)}
function postCard(p){return `<article class="card post"><div class="author"><span class="avatar" aria-hidden="true">${p.author[0]}</span><div><strong>${p.author}</strong><div class="muted">il y a quelques minutes</div></div>${p.own?'<span class="badge">Votre publication</span>':''}</div><p>${p.text}</p>${p.id===2?'<div class="media">Média fictif de l’annonce vélo</div>':''}<div class="post-actions"><button class="secondary button" data-action="like" data-id="${p.id}" ${p.own?'disabled aria-describedby="own-like-help"':''}>${p.liked?'♥ Liké':'♡ J’aime'} ${p.likes}</button><button class="secondary button" data-action="comment" data-id="${p.id}">Commenter</button>${p.own?`<button class="secondary button" data-action="edit-post" data-id="${p.id}">Modifier</button><button class="danger button" data-action="delete-post" data-id="${p.id}">Supprimer</button>`:''}</div>${p.own?'<span id="own-like-help" class="help">Vous ne pouvez pas aimer votre propre publication dans cette cible.</span>':''}${p.comments.map(c=>`<div class="comment">${c}</div>`).join('')}</article>`}
function feed(){let content=scenarioState()||`<div class="feed-layout"><section class="stack"><div class="row between"><div><h1 class="page-title">Feed</h1><p class="lead">Publications et interactions fictives.</p></div><button class="primary button" data-action="compose">Créer une publication</button></div>${state.success?`<div class="notice success">${state.success}</div>`:''}${state.feed.map(postCard).join('')}</section><aside class="stack desktop-only">${controls()}<section class="card"><h2>Raccourcis</h2><button class="text-button" data-screen="profile">Mon profil</button><button class="text-button" data-screen="market">Mes annonces</button></section></aside></div>`;return shell(content)}
function compose(editId){const post=state.feed.find(p=>p.id===editId);return shell(`<section class="card" style="max-width:680px;margin:auto"><h1 class="page-title">${post?'Modifier':'Nouvelle'} publication</h1><form id="post-form" data-edit="${post?.id||''}"><div class="field"><label for="post-text">Votre message</label><textarea id="post-text">${post?post.text:''}</textarea><span class="help">Contenu fictif ; les limites réelles seront contrôlées côté serveur.</span></div><div class="row"><button class="secondary button" type="button" data-screen="feed">Annuler</button><button class="primary button" type="submit">${post?'Enregistrer':'Publier'}</button></div></form></section>`)}
function comments(id){const p=state.feed.find(x=>x.id===id);return shell(`<section class="card" style="max-width:680px;margin:auto"><h1 class="page-title">Commentaires</h1>${p.comments.map(c=>`<p class="comment">${c}</p>`).join('')||'<p class="muted">Aucun commentaire.</p>'}<form id="comment-form" data-id="${id}" class="field"><label for="comment">Ajouter un commentaire</label><input id="comment" value="Message de démonstration"><button class="primary button" type="submit">Envoyer</button></form><button class="secondary button" data-screen="feed">Retour au feed</button></section>`)}
function chat(){const fallback=scenarioState();if(fallback)return shell(`<h1 class="page-title">Chat</h1>${fallback}`);return shell(`<section class="two-col ${state.chatMobileThread?'chat-mobile-thread':'chat-mobile-list'}"><aside class="card"><div class="row between"><h1 class="page-title">Messages</h1><button class="text-button" data-action="new-chat">Nouveau</button></div><ul class="conversation-list"><li><button data-action="open-chat" aria-pressed="${state.chatMobileThread}"><strong>Bruno Demo</strong><br><span class="muted">Bonjour Alice, le vélo est disponible.</span></button></li><li><button data-action="open-chat"><strong>Charlie Demo</strong><br><span class="muted">Discussion sociale</span></button></li></ul></aside><section class="card chat"><div class="chat-header"><button class="text-button" data-action="chat-back">← Conversations</button> Bruno Demo <span class="badge">Marketplace</span></div><div class="messages">${state.messages.map(m=>`<div class="bubble ${m.from==='Alice Demo'?'me':''}"><strong>${m.from}</strong><br>${m.text}</div>`).join('')}</div><form id="message-form" class="message-form"><label class="sr-only" for="message">Votre message</label><input id="message" value="Merci pour ces précisions."><button class="primary button" type="submit">Envoyer</button></form><p class="prototype-note">Prototype UX uniquement — relation technique Listing–Conversation à concevoir.</p></section></section>${controls()}`)}
function market(){const fallback=scenarioState();if(fallback)return shell(`<h1 class="page-title">Marketplace</h1>${fallback}`);if(state.listingOpen)return listingDetail();return shell(`<section><div class="row between"><div><h1 class="page-title">Marketplace</h1><p class="lead">Produits et transactions fictifs.</p></div><button class="primary button" data-action="open-listing">Voir l’annonce démo</button></div><div class="listing-grid"><article class="card listing"><div class="media">Vélo urbain · image fictive</div><h2>Vélo urbain</h2><p>30 crédits démo · Bruno Demo</p><span class="badge ${state.market.toLowerCase()}">${state.market}</span><button class="secondary button" data-action="open-listing">Voir le détail</button></article><article class="card listing"><div class="media">Livre illustré</div><h2>Annonce fictive</h2><p class="muted">État possible : REFUSED</p><span class="badge pending">PENDING</span></article></div>${controls()}</section>`)}
function listingDetail(){const s=state.market;let actions='';if(s==='AVAILABLE')actions=`<button class="primary button" data-action="request">Demander l’achat</button><button class="secondary button" data-action="contact-seller">Contacter le vendeur</button>`;if(s==='PENDING')actions=`<div class="notice warning">Demande envoyée. Simulation vendeur : </div><button class="primary button" data-action="accept">Accepter</button><button class="danger button" data-action="refuse">Refuser</button>`;if(s==='ACCEPTED')actions=`<div class="wallet"><strong>Wallet de démonstration</strong><br>Solde : ${state.wallet} crédits démo<br>Produit : 30 crédits démo</div><button class="primary button" data-action="pay">Payer 30 crédits démo</button>`;if(s==='PAID')actions=`<div class="notice success">Paiement simulé effectué.</div><button class="primary button" data-action="ship">Marquer expédié (vendeur)</button>`;if(s==='SHIPPED')actions=`<div class="notice">Annonce expédiée.</div><button class="primary button" data-action="receive">Confirmer réception (acheteur)</button>`;if(s==='RECEIVED')actions=`<div class="notice success">Réception confirmée. Parcours terminé.</div>`;if(s==='REFUSED')actions=`<div class="notice error">Demande refusée par le vendeur.</div><button class="secondary button" data-action="reset-market">Retour au catalogue</button>`;return shell(`<section class="card" style="max-width:760px;margin:auto"><button class="text-button" data-action="close-listing">← Marketplace</button><div class="media" style="min-height:190px">Vélo urbain · image fictive</div><h1 class="page-title" style="margin-top:18px">Vélo urbain</h1><p class="lead">Bruno Demo · 30 crédits démo</p><div class="status-flow">${['AVAILABLE','PENDING','ACCEPTED','REFUSED','PAID','SHIPPED','RECEIVED'].map(x=>`<span class="${x===s?'current':''}">${x}</span>`).join('')}</div><p>Annonce fictive permettant de démontrer le cycle d’achat et les actions par rôle.</p><div class="row">${actions}</div><p class="prototype-note">Le wallet est une simulation UX : aucun paiement, compte bancaire ou PSP réel n’est utilisé.</p></section>`)}
function profile(){return shell(`<section class="card" style="max-width:650px;margin:auto"><div class="author"><span class="avatar" style="width:64px;height:64px">A</span><div><h1 class="page-title">Alice Demo</h1><p class="muted">alice@example.com · privé</p></div></div><div class="wallet"><strong>Wallet de démonstration</strong><br>${state.wallet} crédits démo</div><div class="row" style="margin-top:16px"><button class="secondary button">Modifier mon profil (simulé)</button><button class="danger button">Supprimer mon compte (confirmation future)</button></div></section>`)}
function modal(title,text,actions){return `<div class="modal-backdrop" role="presentation"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">${title}</h2><p>${text}</p><div class="row">${actions}</div></section></div>`}
function render(){let view=state.screen==='login'?login():state.screen==='register'?register():state.screen==='contract'?contract():state.screen==='feed'?feed():state.screen==='compose'?compose():state.screen.startsWith('edit:')?compose(+state.screen.split(':')[1]):state.screen.startsWith('comments:')?comments(+state.screen.split(':')[1]):state.screen==='chat'?chat():state.screen==='market'?market():profile();app.innerHTML=view;$('#mode')?.addEventListener('change',e=>{state.mode=e.target.value;render()})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-screen],[data-demo]');if(!b)return;if(b.dataset.screen){setScreen(b.dataset.screen);return}if(b.dataset.demo){state.demo=b.dataset.demo;render();return}const a=b.dataset.action;if(a==='logout'){state.auth=false;setScreen('login')}if(a==='wrong-login'){$('#login-error').textContent='Identifiants invalides (simulation).';announce('Erreur de connexion simulée')}if(a==='contract-refused'){$('#login-error').textContent='Contrat non accepté : accès refusé (simulation).'}if(a==='accept-contract'){state.screen='login';render();app.insertAdjacentHTML('beforeend',modal('Compte simulé créé','Vous pouvez maintenant simuler une connexion.', '<button class="primary button" data-action="close-modal">Continuer</button>'))}if(a==='close-modal')render();if(a==='compose')setScreen('compose');if(a==='edit-post')setScreen(`edit:${b.dataset.id}`);if(a==='delete-post'){app.insertAdjacentHTML('beforeend',modal('Supprimer cette publication ?','Cette confirmation simule une action dangereuse.',`<button class="secondary button" data-action="close-modal">Annuler</button><button class="danger button" data-action="confirm-delete" data-id="${b.dataset.id}">Supprimer</button>`))}if(a==='confirm-delete'){state.feed=state.feed.filter(p=>p.id!==+b.dataset.id);state.success='Publication supprimée (simulation).';setScreen('feed')}if(a==='like'){const p=state.feed.find(x=>x.id===+b.dataset.id);if(!p.own){p.liked=!p.liked;p.likes+=p.liked?1:-1;announce(p.liked?'Publication aimée.':'Like retiré.');render()}}if(a==='comment')setScreen(`comments:${b.dataset.id}`);if(a==='open-chat'||a==='contact-seller'){state.chatMobileThread=true;setScreen('chat')}if(a==='chat-back'){state.chatMobileThread=false;render()}if(a==='new-chat'){state.success='Nouvelle conversation : simulation à concevoir.';render()}if(a==='open-listing'){state.listingOpen=true;setScreen('market')}if(a==='close-listing'){state.listingOpen=false;setScreen('market')}if(a==='request'){state.market='PENDING';render()}if(a==='accept'){state.market='ACCEPTED';render()}if(a==='refuse'){state.market='REFUSED';render()}if(a==='pay'){state.wallet=70;state.market='PAID';render()}if(a==='ship'){state.market='SHIPPED';render()}if(a==='receive'){state.market='RECEIVED';render()}if(a==='reset-market'){state.market='AVAILABLE';state.listingOpen=false;setScreen('market')}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='login-form'){const email=$('#email').value;if(!/^\S+@\S+\.\S+$/.test(email)){$('#email-error').textContent='Saisissez un email valide.';return}state.auth=true;state.screen='feed';state.success='Connexion simulée réussie.';render()}if(e.target.id==='register-form'){setScreen('contract')}if(e.target.id==='post-form'){const text=$('#post-text').value.trim(),id=+e.target.dataset.edit;if(!text){return}if(id){state.feed.find(p=>p.id===id).text=text;state.success='Publication modifiée (simulation).'}else{state.feed.unshift({id:Date.now(),author:'Alice Demo',own:true,text,likes:0,liked:false,comments:[]});state.success='Publication publiée (simulation).'}setScreen('feed')}if(e.target.id==='comment-form'){const p=state.feed.find(x=>x.id===+e.target.dataset.id);p.comments.push(`Alice Demo : ${$('#comment').value}`);setScreen('feed')}if(e.target.id==='message-form'){state.messages.push({from:'Alice Demo',text:$('#message').value});announce('Message ajouté au prototype.');render()}});
render();
